solution.solution.cpp:
#include <cctype>
#include <string>
#include <vector>

struct FileType { std::string description; std::string patterns; };

std::string buildFilter(const std::vector<FileType>& types)
{
    std::string out;
    for (const FileType& t : types) { out += t.description; out += '\0'; out += t.patterns; out += '\0'; }
    out += '\0';
    return out;
}

std::vector<FileType> parseFilter(const std::string& filter)
{
    std::vector<std::string> parts;
    std::size_t pos{ 0 };
    while (pos < filter.size())
    {
        const std::size_t end{ filter.find('\0', pos) };
        const std::string part{ filter.substr(pos, end == std::string::npos ? std::string::npos : end - pos) };
        if (part.empty()) break;
        parts.push_back(part);
        if (end == std::string::npos) break;
        pos = end + 1;
    }
    std::vector<FileType> types;
    for (std::size_t i{ 0 }; i + 1 < parts.size(); i += 2) types.push_back({ parts[i], parts[i + 1] });
    return types;
}

std::string defaultExtension(const FileType& type)
{
    const std::string first{ type.patterns.substr(0, type.patterns.find(';')) };
    if (first.size() < 3 || first.rfind("*.", 0) != 0) return "";
    const std::string ext{ first.substr(2) };
    for (char c : ext) if (!std::isalnum(static_cast<unsigned char>(c))) return "";
    return ext;
}

std::string finalSaveName(const std::string& typed, const FileType& selected)
{
    const auto b{ typed.find_first_not_of(' ') };
    if (b == std::string::npos) return "";
    const std::string name{ typed.substr(b, typed.find_last_not_of(' ') - b + 1) };
    const auto slash{ name.rfind('\\') };
    const std::string file{ slash == std::string::npos ? name : name.substr(slash + 1) };
    const auto dot{ file.rfind('.') };
    if (dot != std::string::npos && dot != 0) return name;
    const std::string ext{ defaultExtension(selected) };
    return ext.empty() ? name : name + "." + ext;
}

unitTests:
const std::vector<FileType> types{ { "Text documents (*.txt;*.md)", "*.txt;*.md" }, { "All files (*.*)", "*.*" } };
TEST("building") {
    const std::string f = buildFilter(types);
    CHECK_EQ(f, std::string("Text documents (*.txt;*.md)\0*.txt;*.md\0All files (*.*)\0*.*\0\0", 60)); CHECK_EQ(f.size(), std::size_t{ 60 });
    CHECK_EQ(buildFilter({}), std::string(1, '\0'));
}
TEST("reading back") {
    const auto back = parseFilter(buildFilter(types)); CHECK_EQ(back.size(), std::size_t{ 2 }); CHECK_EQ(back[1].description, std::string("All files (*.*)")); CHECK_EQ(back[0].patterns, std::string("*.txt;*.md"));
    CHECK_EQ(parseFilter(std::string("Images\0*.png\0Orphan", 19)).size(), std::size_t{ 1 }); CHECK(parseFilter(std::string(1, '\0')).empty());
}
TEST("default extensions") { CHECK_EQ(defaultExtension(types[0]), std::string("txt")); CHECK_EQ(defaultExtension(types[1]), std::string("")); CHECK_EQ(defaultExtension({ "Backups", "*.bak2" }), std::string("bak2")); CHECK_EQ(defaultExtension({ "Odd", "report*.txt" }), std::string("")); }
TEST("the saved name") {
    CHECK_EQ(finalSaveName("notes", types[0]), std::string("notes.txt")); CHECK_EQ(finalSaveName("  notes.md ", types[0]), std::string("notes.md"));
    CHECK_EQ(finalSaveName("notes", types[1]), std::string("notes")); CHECK_EQ(finalSaveName(".env", types[0]), std::string(".env.txt"));
    CHECK_EQ(finalSaveName("C:\\v1.2\\notes", types[0]), std::string("C:\\v1.2\\notes.txt")); CHECK_EQ(finalSaveName("   ", types[0]), std::string(""));
}

